import 'package:cozy_life_adventure/game/state/player_event_journal.dart';
import 'package:flutter_test/flutter_test.dart';

void main() {
  test('aggregates repeated occurrences without growing unique facts', () {
    final journal = PlayerEventJournal()
        .record(
          kind: PlayerEventKind.areaEntered,
          subjectId: 'woods',
          activeSeconds: 12,
        )
        .record(
          kind: PlayerEventKind.areaEntered,
          subjectId: 'woods',
          activeSeconds: 31,
        )
        .record(
          kind: PlayerEventKind.itemGifted,
          subjectId: 'moonflower',
          targetId: 'npc-01',
          activeSeconds: 35,
        );

    expect(journal.facts, hasLength(2));
    expect(journal.lastSequence, 3);
    final woods = journal.find(
      kind: PlayerEventKind.areaEntered,
      subjectId: 'woods',
    )!;
    expect(woods.count, 2);
    expect(woods.firstSequence, 1);
    expect(woods.lastSequence, 2);
    expect(woods.firstActiveSeconds, 12);
    expect(woods.lastActiveSeconds, 31);
  });

  test('matches count bounds and active-play recency', () {
    final journal = PlayerEventJournal().record(
      kind: PlayerEventKind.resourceGathered,
      subjectId: 'moonflower',
      activeSeconds: 40,
    );

    expect(
      journal.matches(
        const PlayerEventCondition(
          kind: PlayerEventKind.resourceGathered,
          subjectId: 'moonflower',
          minimumCount: 1,
          maximumCount: 1,
          occurredWithinActiveSeconds: 15,
        ),
        nowSeconds: 55,
      ),
      isTrue,
    );
    expect(
      journal.matches(
        const PlayerEventCondition(
          kind: PlayerEventKind.resourceGathered,
          subjectId: 'moonflower',
          occurredWithinActiveSeconds: 15,
        ),
        nowSeconds: 55.01,
      ),
      isFalse,
    );
  });

  test('unknown migrated timestamps never pretend to be recent', () {
    final journal = PlayerEventJournal(
      lastSequence: 2,
      facts: {
        const PlayerEventKey(
          kind: PlayerEventKind.areaEntered,
          subjectId: 'woods',
        ): const PlayerEventFact(
          count: 2,
          firstSequence: 1,
          lastSequence: 2,
          firstActiveSeconds: null,
          lastActiveSeconds: null,
        ),
      },
    );

    expect(
      journal.matches(
        const PlayerEventCondition(
          kind: PlayerEventKind.areaEntered,
          subjectId: 'woods',
          minimumCount: 2,
        ),
        nowSeconds: 100,
      ),
      isTrue,
    );
    expect(
      journal.matches(
        const PlayerEventCondition(
          kind: PlayerEventKind.areaEntered,
          subjectId: 'woods',
          occurredWithinActiveSeconds: 1000,
        ),
        nowSeconds: 100,
      ),
      isFalse,
    );
  });
}
